#!/usr/bin/env python3
"""Regenerate docs/data-contract.md from the SQL views and the DAB config."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
from check_contract import view_columns  # noqa: E402

views = view_columns((ROOT / "sql" / "30_contract_views.sql").read_text(encoding="utf-8"))
cfg = json.loads((ROOT / "dab" / "dab-config.json").read_text())

out = [
    "# CIP data contract",
    "",
    "Generated by `tools/gen_contract_doc.py` from `sql/30_contract_views.sql` and `dab/dab-config.json`.",
    "Do not edit by hand.",
    "",
    "Every entity is a SQL view in schema `contract`, exposed read-only by Data API builder to the role",
    "`client_reader`. Rows are filtered to the caller's `client_code` claim by row-level security in the",
    "database before DAB sees them.",
    "",
    "| Endpoint | GraphQL list | Key | Columns | Description |",
    "|---|---|---|---|---|",
]
for name, e in cfg["entities"].items():
    keys = ", ".join(f["name"] for f in e.get("fields", []) if f.get("primary-key"))
    gql = e["graphql"]["type"]["plural"]
    gql = gql[0].lower() + gql[1:]
    cols = len(views[name])
    out.append(f"| `GET /api/{name}` | `{gql}` | `{keys}` | {cols} | {e.get('description', '')} |")

out += ["", "## Columns", ""]
for name, cols in views.items():
    out.append(f"**{name}** — " + ", ".join(f"`{c}`" for c in cols))
    out.append("")

out += [
    "## Query options",
    "",
    "Standard DAB REST options work on every endpoint: `$select`, `$filter`, `$orderby`, `$first`, `$after`.",
    "Example: `GET /api/vw_activity?$orderby=event_id desc&$first=15`.",
    "",
    "## Conventions",
    "",
    "- Amounts are AED (`*_aed`); the console divides by 1e6 for AED m.",
    "- Percentages are 0-100 with one decimal (`*_pct`).",
    "- Timestamps are UTC `datetime2` serialised without a zone suffix.",
    "- A column change is a contract change: update the view, the DAB config, the emulator and run",
    "  `python3 tools/check_contract.py`.",
    "",
]
(ROOT / "docs").mkdir(exist_ok=True)
(ROOT / "docs" / "data-contract.md").write_text("\n".join(out), encoding="utf-8")
print("wrote docs/data-contract.md")
